.btn-primary::before{content: ""; position: absolute; inset: 0px; background: linear-gradient(135deg, oklch(0.85 0.05 0 / 0.4) 0%, transparent 50%, oklch(0.85 0.05 0 / 0.2) 100%); opacity: 0; transition: opacity 0.3s; mask-image: radial-gradient(circle at var(--mx, 50%) var(--my, 50%), black 30%, transparent 70%);}
.btn-primary:hover{box-shadow: oklch(0.65 0.3 330 / 0.4) 0px 0px 30px 8px, oklch(0.6 0.2 250 / 0.2) 0px 0px 60px 20px; transform: translateY(-1px);}
.btn-primary:hover::before{opacity: 1;}
.btn-ghost{position: relative; padding: 0.85rem 2.2rem; font-size: 0.75rem; font-weight: 500; letter-spacing: 0.15em; text-transform: uppercase; font-family: "JetBrains Mono", monospace; color: var(--text-secondary); background: transparent; border: 1px solid oklch(1 0 0 / 0.08); border-radius: 2px; cursor: none; overflow: hidden; transition: color 0.3s, border-color 0.3s;}
.btn-ghost:hover{color: var(--text-primary); border-color: oklch(1 0 0 / 0.2);}
.metrics-bar{display: flex; gap: 3rem; padding: 2rem 0px; border-top: 1px solid var(--glass-edge); margin-top: 5rem;}
.metric-item{flex: 1 1 0%;}
.metric-value{font-size: clamp(2rem, 4vw, 3.5rem); font-weight: 800; line-height: 1; letter-spacing: -0.03em; background-image: ; background-position-x: ; background-position-y: ; background-size: ; background-repeat: ; background-attachment: ; background-origin: ; background-color: ; -webkit-text-fill-color: transparent; background-clip: text;}
.metric-label{font-family: "JetBrains Mono", monospace; font-size: 0.6rem; font-weight: 400; letter-spacing: 0.2em; text-transform: uppercase; color: var(--text-secondary); margin-top: 0.4rem;}
.bento-section{padding: 6rem 0px;}
.section-header{display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 3rem;}
.section-title{font-size: clamp(1.8rem, 3vw, 2.8rem); font-weight: 700; letter-spacing: -0.03em; line-height: 1;}
.section-tag{font-family: "JetBrains Mono", monospace; font-size: 0.6rem; letter-spacing: 0.2em; text-transform: uppercase; color: var(--text-accent-m); padding-bottom: 0.3rem;}
.bento-grid{display: grid; grid-template-columns: repeat(12, 1fr); grid-template-rows: auto; gap: 1px; background: oklch(1 0 0 / 0.04); border: 1px solid oklch(1 0 0 / 0.04); border-radius: 4px; overflow: hidden;}
.bento-cell{background: var(--glass-surface); padding: 2.5rem; position: relative; overflow: hidden; transition: background 0.4s;}
.bento-cell::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(ellipse at var(--cx, 50%) var(--cy, 50%), oklch(65% 0.3 330 / 0.06) 0%, transparent 60%); opacity: 0; transition: opacity 0.4s;}
.bento-cell:hover::before{opacity: 1;}
.bento-cell:hover{background: oklch(0.14 0.05 250 / 0.7);}
.cell-a{grid-area: 1 / 1 / 2 / 6;}
.cell-b{grid-area: 1 / 6 / 2 / 9;}
.cell-c{grid-area: 1 / 9 / 3 / 13;}
.cell-d{grid-area: 2 / 1 / 3 / 4;}
.cell-e{grid-area: 2 / 4 / 3 / 6;}
.cell-f{grid-area: 2 / 6 / 3 / 9;}
.cell-g{grid-area: 3 / 1 / 4 / 5;}
.cell-h{grid-area: 3 / 5 / 4 / 9;}
.cell-i{grid-area: 3 / 9 / 4 / 13;}
.cell-label{font-family: "JetBrains Mono", monospace; font-size: 0.55rem; font-weight: 500; letter-spacing: 0.2em; text-transform: uppercase; color: var(--text-accent-m); margin-bottom: 1.2rem; display: flex; align-items: center; gap: 0.6rem;}
.cell-label::before{content: ""; display: block; width: 1rem; height: 1px; background: currentcolor; box-shadow: currentcolor 0px 0px 4px;}
.cell-heading{font-size: clamp(1.4rem, 2.5vw, 2.2rem); font-weight: 700; letter-spacing: -0.025em; line-height: 1.05; margin-bottom: 1rem;}
.cell-body{font-size: 0.82rem; line-height: 1.75; color: var(--text-secondary); font-weight: 300;}
.cell-number{font-size: clamp(3rem, 6vw, 5.5rem); font-weight: 800; letter-spacing: -0.05em; line-height: 1; background-image: ; background-position-x: ; background-position-y: ; background-size: ; background-repeat: ; background-attachment: ; background-origin: ; background-color: ; -webkit-text-fill-color: transparent; background-clip: text;}
.cell-number-unit{font-family: "JetBrains Mono", monospace; font-size: 0.65rem; letter-spacing: 0.15em; color: var(--text-secondary); margin-top: 0.5rem;}
.inset-card{box-shadow: oklch(0 0 0 / 0.5) 0px 2px 4px inset, oklch(1 0 0 / 0.04) 0px -1px 2px inset, oklch(0 0 0 / 0.3) 2px 0px 4px inset, oklch(0 0 0 / 0.3) -2px 0px 4px inset, oklch(1 0 0 / 0.06) 0px 1px 0px; background: oklch(0.06 0.03 250 / 0.8);}
.flow-diagram{display: flex; flex-direction: column; gap: 0.8rem; margin-top: 1.5rem;}
.flow-node{display: flex; align-items: center; gap: 1rem; padding: 0.7rem 1rem; background: oklch(0.08 0.04 250 / 0.6); border-radius: 2px; border-left: 2px solid transparent; transition: border-color 0.3s, background 0.3s; position: relative; overflow: hidden;}
.flow-node::after{content: ""; position: absolute; left: 0px; top: 0px; bottom: 0px; width: 0%; background: linear-gradient(90deg, oklch(0.65 0.3 330 / 0.1), transparent); transition: width 0.6s cubic-bezier(0.16, 1, 0.3, 1);}
.flow-node:hover::after{width: 100%;}
.flow-node:hover{border-left-color: var(--neon-magenta);}
.flow-node-icon{width: 28px; height: 28px; border-radius: 1px; display: flex; align-items: center; justify-content: center; font-size: 0.65rem; flex-shrink: 0; font-family: "JetBrains Mono", monospace; font-weight: 700;}
.flow-node-text{font-size: 0.75rem; color: var(--text-secondary); font-weight: 400;}
.flow-node-val{font-family: "JetBrains Mono", monospace; font-size: 0.65rem; color: var(--text-accent-c); margin-left: auto;}
.spectrum-bar{height: 4px; border-radius: 2px; background: linear-gradient(90deg, var(--neon-magenta), var(--electric-cyan)); box-shadow: oklch(0.65 0.3 330 / 0.4) 0px 0px 12px 2px; margin-bottom: 0.8rem; position: relative; overflow: hidden;}
.spectrum-bar::after{content: ""; position: absolute; inset: 0px; background: linear-gradient(90deg, transparent, oklch(1 0 0 / 0.4), transparent); animation: 2.5s ease-in-out 0s infinite normal none running shimmer-bar;}
@keyframes shimmer-bar { 
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}
.neural-grid{position: absolute; inset: 0px; opacity: 0.06; background-image: linear-gradient(oklch(1 0 0) 1px, transparent 1px), linear-gradient(90deg, oklch(1 0 0) 1px, transparent 1px); background-size: 40px 40px; pointer-events: none;}
.data-stream{margin-top: 1.5rem; display: flex; flex-direction: column; gap: 0.5rem;}
.stream-row{display: flex; justify-content: space-between; align-items: center; padding: 0.5rem 0px; border-bottom: 1px solid oklch(1 0 0 / 0.04); font-family: "JetBrains Mono", monospace;}
.stream-key{font-size: 0.6rem; color: var(--text-secondary); letter-spacing: 0.1em; text-transform: uppercase;}
.stream-val{font-size: 0.7rem; color: var(--text-accent-c); font-weight: 600;}
.velocity-section{padding: 8rem 0px; position: relative;}
.velocity-text{font-size: clamp(4rem, 10vw, 10rem); font-weight: 900; letter-spacing: -0.06em; line-height: 0.85; color: oklch(1 0 0 / 0.03); text-transform: uppercase; user-select: none; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); white-space: nowrap; font-variation-settings: 'wght' var(--velocity-weight, 900);}
.velocity-content{position: relative; z-index: 2; display: grid; grid-template-columns: 1fr 1fr; gap: 6rem; align-items: center; padding: 4rem 0px;}
.velocity-headline{font-size: clamp(2rem, 4vw, 3.5rem); font-weight: 700; letter-spacing: -0.03em; line-height: 1; margin-bottom: 1.5rem;}
.velocity-desc{font-size: 0.875rem; line-height: 1.8; color: var(--text-secondary); font-weight: 300; margin-bottom: 2rem;}
.kinetic-counter{display: flex; flex-direction: column; gap: 2rem;}
.counter-item{display: flex; align-items: center; gap: 1.5rem; padding: 1.5rem; background: oklch(0.08 0.04 250 / 0.5); border: 1px solid var(--glass-edge); border-radius: 2px; position: relative; overflow: hidden;}
.counter-item::before{content: ""; position: absolute; left: 0px; top: 0px; bottom: 0px; width: 3px; background: linear-gradient(180deg, var(--neon-magenta), var(--electric-cyan)); box-shadow: oklch(0.65 0.3 330 / 0.6) 0px 0px 12px 2px;}
.counter-num{font-size: 2.2rem; font-weight: 800; letter-spacing: -0.04em; line-height: 1; color: var(--text-primary); white-space: nowrap;}
.counter-label{font-size: 0.75rem; color: var(--text-secondary); font-weight: 300; line-height: 1.5;}
.counter-sub{font-family: "JetBrains Mono", monospace; font-size: 0.6rem; color: var(--text-accent-c); margin-top: 0.25rem;}
.scan-line{position: fixed; top: 0px; left: 0px; width: 100%; height: 2px; background: linear-gradient(90deg, transparent, var(--neon-magenta), var(--electric-cyan), transparent); z-index: 200; animation: 8s cubic-bezier(0.16, 1, 0.3, 1) 0s infinite normal none running scan; opacity: 0.6; box-shadow: oklch(0.65 0.3 330 / 0.4) 0px 0px 20px 4px;}
@keyframes scan { 
  0% { top: -4px; opacity: 0; }
  2% { opacity: 0.6; }
  98% { opacity: 0.6; }
  100% { top: 100vh; opacity: 0; }
}
.noise-overlay{position: fixed; inset: 0px; z-index: 5; pointer-events: none; opacity: 0.025; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(https://openhero.art/api/%23noise)'/%3E%3C/svg%3E"); background-size: 256px 256px;}
.glow-orb{position: fixed; border-radius: 50%; pointer-events: none; filter: blur(80px); z-index: 0; animation: 20s ease-in-out 0s infinite normal none running orb-drift;}
.orb-1{width: 600px; height: 600px; background: oklch(0.65 0.3 330 / 0.06); top: -200px; left: -100px; animation-delay: 0s;}
.orb-2{width: 500px; height: 500px; background: oklch(0.6 0.2 250 / 0.07); bottom: -150px; right: 30%; animation-delay: -10s;}
@keyframes orb-drift { 
  0%, 100% { transform: translate(0px, 0px) scale(1); }
  33% { transform: translate(40px, -30px) scale(1.05); }
  66% { transform: translate(-20px, 50px) scale(0.95); }
}
.tag-pill{display: inline-flex; align-items: center; gap: 0.4rem; padding: 0.3rem 0.8rem; background: oklch(0.6 0.2 250 / 0.1); border: 1px solid oklch(0.6 0.2 250 / 0.2); border-radius: 100px; font-family: "JetBrains Mono", monospace; font-size: 0.58rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-accent-c);}
.scroll-indicator{position: fixed; right: 2rem; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 0.5rem; z-index: 50; align-items: center;}
.scroll-indicator-line{width: 1px; height: 60px; background: linear-gradient(180deg, transparent, var(--neon-magenta), transparent); animation: 3s ease-in-out 0s infinite normal none running scroll-line;}
@keyframes scroll-line { 
  0%, 100% { opacity: 0.2; transform: scaleY(0.5); }
  50% { opacity: 0.8; transform: scaleY(1); }
}
.scroll-label{font-family: "JetBrains Mono", monospace; font-size: 0.5rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--text-secondary); writing-mode: vertical-rl; transform: rotate(180deg);}
@keyframes fade-in-up { 
  0% { opacity: 0; transform: translateY(20px); }
  100% { opacity: 1; transform: translateY(0px); }
}
.delay-1{animation-delay: 0.1s;}
.delay-2{animation-delay: 0.2s;}
.delay-3{animation-delay: 0.3s;}
.delay-4{animation-delay: 0.5s;}
.delay-5{animation-delay: 0.7s;}
@keyframes trail-appear { 
  0% { opacity: 0; height: 0px; }
  100% { opacity: 0.4; height: 80px; }
}
.progress-ring{transform: rotate(-90deg);}
.ring-track{fill: none; stroke: oklch(1 0 0 / 0.06); stroke-width: 2;}
.ring-fill{fill: none; stroke: url("#ring-gradient"); stroke-width: 2; stroke-linecap: round; transition: stroke-dashoffset 2s cubic-bezier(0.16, 1, 0.3, 1);}
h1, h2{font-size: inherit; font-weight: inherit;}
button{font-family: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-size: 100%; font-weight: inherit; line-height: inherit; letter-spacing: inherit; color: inherit; margin: 0px; padding: 0px;}
button{text-transform: none;}
button{appearance: button; background-color: transparent; background-image: none;}
h1, h2{margin: 0px;}
button{cursor: pointer;}
canvas, svg, video{display: block; vertical-align: middle;}
video{max-width: 100%; height: auto;}
.mt-4{margin-top: 1rem;}
.flex{display: flex;}
.h-8{height: 2rem;}
.items-end{align-items: flex-end;}
.gap-1{gap: 0.25rem;}

